function winEnemy(){let e=S.enemy;let gold=e.goldMin+rnd(Math.max(1,e.goldMax-e.goldMin+1));gold=Math.floor(gold*(1+(S.skills.fortune||0)*.1)*(1+S.prestige*.05));S.gold+=gold;gainXp(e.xp);S.kills++;if(S.quest.date!==today())resetQuest();S.quest.count++;S.dungeonWins+=S.dungeonMode?1:0;let heal=Math.floor(effective().hp*(S.skills.siphon||0)*.05);if(heal)S.hp=Math.min(effective().hp,(S.hp??effective().hp)+heal);log(`${e.boss?'Boss besiegt! ':''}${e.name} bezwungen: +${gold} Gold, +${e.xp} EP.`,'positive');toast(`+${gold} Gold  ·  +${e.xp} EP`,'good');let chance=e.boss?.100:e.elite?.75:.34;if(Math.random()<chance)dropItem(e.boss?2:undefined);if(e.boss){S.bossKills++;S.unlockedArea=Math.max(S.unlockedArea,S.area+1);S.area=Math.max(S.area,S.unlockedArea);S.dungeonDate='';S.dungeonWins=0;S.dungeonMode=false;toast(`Gebiet ${S.area} freigeschaltet!`,'good');log(`Der Boss hat den Weg nach ${areaData(S.area)[0]} geöffnet.`,'positive')}else if(!S.dungeonMode&&S.kills%5===0){S.unlockedArea=Math.max(S.unlockedArea,S.area+1);if(S.area< S.unlockedArea){S.area=S.unlockedArea;log(`Neue Region entdeckt: ${areaData(S.area)[0]}!`,'positive');toast(`Gebiet ${S.area}: ${areaData(S.area)[0]}`,'good')}}if(S.dungeonMode&&S.dungeonWins>=3){S.dungeonMode=false;S.dungeonDate=today();dropItem(2,true);S.gold+=Math.floor(25+S.area*7);toast('Dungeon geschafft! Garantierte seltene Beute!','good');log('Die Dungeontruhe ist dein.','positive')}checkAchievements();S.enemy=null;nextEnemy();update();save()}
