function itemTemplate(slot,rarityIdx,level=S.level,upgrade=0){let r=rarity(rarityIdx),data=slots.find(s=>s[0]===slot)||slots[0];let base=Math.max(1,Math.floor((2+level*.9)*r.mult*(1+upgrade*.22)));let stats={attack:0,defense:0,hp:0,crit:0,speed:0};if(slot==='weapon')stats.attack=base*2;else if(['helmet','chest','gloves','legs','boots'].includes(slot)){stats.defense=Math.max(1,Math.floor(base*.7));if(slot==='chest')stats.hp=base*5;else if(slot==='boots')stats.speed=Math.max(1,Math.floor(base*.22))}else{stats.hp=base*2;stats.crit=Math.max(1,Math.floor(base*.18));if(slot==='ring')stats.attack=Math.floor(base*.55)}if(rarityIdx>=4){if(Math.random()<.6)stats.crit+=rarityIdx; if(rarityIdx>=5)stats.hp+=base*2}let names={weapon:['Klinge','Langschwert','Runenbrecher','Mondklinge','Weltenklinge'],helmet:['Haube','Waldhüterhelm','Runendiadem','Nebelkrone'],chest:['Wams','Schuppenpanzer','Herzplatte','Sternenrüstung'],gloves:['Griffe','Jägerhandschuhe','Runenfäuste'],legs:['Beinschienen','Wurzelgreife','Schattenbeinschutz'],boots:['Stiefel','Pfadfinderstiefel','Windläufer'],ring:['Ring','Siegelring','Sternenband'],amulet:['Talisman','Amulett','Seelenanhänger','Götterzeichen']};let word=names[slot][rnd(names[slot].length)];let prefix=['','des Wanderers','der Dämmerung','des uralten Wächters','der Ewigkeit','der Sternenseele','des ersten Lichts'][rarityIdx];let special=rarityIdx>=4?['Glutseele','Weltenriss','Sternenherz','Ewiger Schwur'][rnd(4)]:'';return{id:'i'+Date.now()+Math.random().toString(16).slice(2),slot,slotName:data[1],icon:data[2],name:(special?special+' ':'')+word+(prefix?' '+prefix:''),rarity:rarityIdx,level,upgrade,stats,special:rarityIdx>=4?['+8% Schaden gegen Bosse','+5% Lebensraub','+10% Goldfund'][rnd(3)]:''}}
function dropItem(fixedRarity,guaranteed=false){let weights=[50,26,13,7,3,1,.25];let luck=(S.skills.fortune||0)*.015+S.prestige*.01;if(fixedRarity===undefined){let roll=Math.random()*100,threshold=100;let idx=0;for(let i=0;i<weights.length;i++){threshold-=weights[i]*(1+luck);if(roll>threshold)idx=i}fixedRarity=Math.min(6,Math.floor(Math.random()<.05+luck?2+rnd(3):Math.random()<.12+luck?1:0))}let slot=slots[rnd(slots.length)][0];let item=itemTemplate(slot,fixedRarity,Math.max(1,enemyScale()),0);S.inventory.unshift(item);S.inventory=S.inventory.slice(0,60);log(`Beute gefunden: ${item.name} (${rarity(item.rarity).name})!`,'positive');toast(`Beute: ${item.name}`,'good');return item}
