function upgradeItem(item){let cost=Math.floor((20+item.level*9+item.upgrade*28)*Math.pow(item.rarity+1,.65));if(S.gold<cost){toast('Nicht genug Gold!','bad');return}S.gold-=cost;item.upgrade++;Object.keys(item.stats).forEach(k=>{if(item.stats[k]>0)item.stats[k]=Math.ceil(item.stats[k]*1.18)});log(`${item.name} auf +${item.upgrade} verbessert.`,'positive');toast(`Aufwertung erfolgreich: +${item.upgrade}`,'good');update();save()}
function combine(item){let dupe=S.inventory.find(i=>i.id!==item.id&&i.slot===item.slot&&i.rarity===item.rarity&&i.level===item.level);if(!dupe){toast('Kein identisches Item zum Verschmelzen gefunden.','bad');return}if(item.rarity>=6){toast('Göttliche Items können nicht weiter verschmolzen werden.');return}S.inventory=S.inventory.filter(i=>i.id!==item.id&&i.id!==dupe.id);let result=itemTemplate(item.slot,item.rarity+1,item.level,Math.max(item.upgrade,dupe.upgrade));result.name=result.name;S.inventory.unshift(result);S.selectedItem=null;S.gold+=Math.floor(10+item.rarity*8);log(`Zwei ${rarity(item.rarity).name}e Gegenstände verschmolzen zu ${rarity(result.rarity).name}!`,'positive');toast(`Verschmolzen: ${result.name}`,'good');update();save()}
