ase()} · ${areaData(S.area)[1].split(' ')[0].toLocaleUpperCase()}`;$('crumb-area').textContent=areaData(S.area)[0].toLocaleUpperCase();let e=S.enemy;if(e){$('enemy-emoji').textContent=e.emoji;$('enemy-name').textContent=e.name;$('target-title').innerHTML=`${esc(e.name)} <span>${e.boss?'♛':e.elite?'✦':'◈'}</span>`;$('enemy-rank').textContent=e.rank;$('enemy-level').textContent=`LVL ${e.level}`;$('enemy-hp').textContent=Math.max(0,e.hp);$('enemy-maxhp').textContent=e.maxHp;$('enemy-hp-fill').style.width=`${Math.max(0,e.hp/e.maxHp*100)}%`;$('enemy-attack').textContent=e.attack;$('enemy-xp').textContent=e.xp;$('enemy-gold').textContent=`${e.goldMin}–${e.goldMax}`;$('enemy-wrap').classList.toggle('boss-enemy',e.boss)}$('gear-preview').innerHTML=slots.map(([id,name,icon])=>{let i=S.equipment[id];return `<div class="gear-slot ${i?'':'empty'}" title="${i?esc(i.name):name}">${i?i.icon:icon}<span>${name.slice(0,4).toUpperCase()}</span></div>`}).join('');renderLog();if($('view-character').classList.contains('active-view'))renderCharacter();if($('view-inventory').classList.contains('active-view'))renderInventory();if($('view-skills').classList.contains('active-view'))renderSkills();if($('view-world').classList.contains('active-view'))renderWorld();save()}

